  font-size: 20px;
  letter-spacing: -0.02em;
  color: var(--text);
}

.brand-name::before {
  content: '[ ';
  color: var(--accent);
}

.brand-name::after {
  content: ' ]';
  color: var(--accent);
}

.header-right {
  display: flex;
  align-items: center;
  gap: 12px;
}

.sys-ver {
  font-size: 10px;
  color: var(--text-dim);
  letter-spacing: 0.12em;
  padding: 3px 8px;
  border: 1px solid var(--border);
}

.llm-badge {
  font-size: 10px;
  letter-spacing: 0.08em;
  padding: 3px 10px;
  border: 1px solid var(--border);
  white-space: nowrap;
}

.llm-badge.on {
  color: var(--text);
  border-color: var(--accent);
  background: var(--accent-soft);
}

.llm-badge.off {
  color: var(--warn);
}

/* ── banners ───────────────────────────────────────────────────────── */
.banner {
  padding: 9px 18px;
  font-size: 11px;
  letter-spacing: 0.04em;
  border-bottom: 1px solid var(--border);
}

.banner.error {
  background: var(--accent-soft);
  color: var(--accent-hi);
  border-bottom: 2px solid var(--accent);
  cursor: pointer;
}

.banner.info {
  color: var(--warn);
  border-bottom: 1px solid var(--warn);
  background: rgba(255, 176, 0, 0.06);
}

.banner.warn {
  color: var(--accent-hi);
  border-bottom: 1px solid var(--accent);
  background: rgba(255, 110, 64, 0.08);
}

.banner code {
  background: rgba(0, 0, 0, 0.5);
  padding: 1px 6px;
  font-size: 10px;
  border: 1px solid var(--border);
}

.banner-close {
  float: right;
}

/* ── page scaffold ─────────────────────────────────────────────────── */
.page {
  flex: 1;
  overflow-y: auto;
  padding: 22px;
  max-width: 980px;
  width: 100%;
  margin: 0 auto;
}

.muted {
  color: var(--text-dim);
}

.flex-spacer {
  flex: 1;
}

/* ── buttons: mechanical keys ──────────────────────────────────────── */
button {
  background: var(--accent);
  color: #fff;
  border: 1px solid var(--accent);
  padding: 8px 14px;
  font-family: var(--mono);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  cursor: pointer;
  user-select: none;
}

button:hover:not(:disabled) {
  background: var(--accent-hi);
}

button:active:not(:disabled) {
  transform: translateY(1px);
}

button.secondary {
  background: transparent;
  border: 1px solid var(--border-strong);
  color: var(--text);
}

button.secondary:hover:not(:disabled) {
  border-color: var(--accent);
  color: var(--accent-hi);
  background: transparent;
}

button.danger {
  background: transparent;
  border: 1px solid var(--accent);
  color: var(--accent-hi);
}

button.tiny {
  padding: 3px 9px;
  font-size: 10px;
}

button:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

.link-btn {
  background: none;
  border: none;
  color: var(--accent-hi);
  padding: 0;
  font-size: 11px;
  letter-spacing: 0.08em;
  cursor: pointer;
  text-transform: uppercase;
}

/* ── module (card) frame ───────────────────────────────────────────── */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  padding: 18px;
  margin-bottom: 16px;
  position: relative;
}

.card::before {
  /* structural top hairline — modules are bolted to the grid */
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: repeating-linear-gradient(90deg, var(--accent) 0 14px, transparent 14px 26px);
  opacity: 0.55;
}

.card h2 {
  margin: 0 0 14px;
  font-size: 13px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--text);
}

.card h2::before {
  content: '/// ';
  color: var(--accent);
}

/* ── upload bay ────────────────────────────────────────────────────── */
.upload {
  text-align: center;
  cursor: pointer;
  border-style: dashed;
  border-width: 2px;
  padding: 34px 18px;
  transition: border-color 0.15s, background 0.15s;
}

.upload.dragging {
  border-color: var(--accent);
  background: var(--accent-soft);
}

.upload-icon {
  font-family: var(--mono);
  font-size: 22px;
  color: var(--accent);
  letter-spacing: 0.2em;
}

.upload h2 {
  margin: 10px 0 6px;
  font-family: var(--macro);
  font-size: 26px;
  letter-spacing: 0.02em;
  text-transform: uppercase;
}

.upload h2::before {
  content: '';
}

.upload .muted {
  font-size: 11px;
  letter-spacing: 0.06em;
}

/* ── document registry ─────────────────────────────────────────────── */
.doc-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.doc-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 12px 6px;
  border-bottom: 1px solid var(--border);
}

.doc-row:last-child {
  border-bottom: none;
}

.doc-row:hover {
  background: rgba(255, 255, 255, 0.02);
}

.doc-main {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}

.doc-name {
  font-weight: 700;
  letter-spacing: 0.03em;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.doc-meta {
  font-size: 10px;
  color: var(--text-dim);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

/* pipeline stage timing breakdown (parse · llm · total) */
.stage-times {
  font-family: var(--mono);
  font-size: 10px;
  color: var(--text-dim);
  letter-spacing: 0.06em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.doc-error {
  color: var(--accent-hi);
  font-size: 10px;
  letter-spacing: 0.04em;
}

.doc-side {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-shrink: 0;
}

.status {
  font-size: 10px;
  letter-spacing: 0.1em;
  color: var(--text-dim);
  min-width: 74px;
  text-align: right;
  font-weight: 700;
}

.status.done {
  color: var(--ok); /* the one terminal-green element */
  text-shadow: 0 0 8px rgba(74, 246, 38, 0.45); /* phosphor glow */
}

.status.error {
  color: var(--accent-hi);
}

.progress-wrap {
  width: 100px;
  height: 8px;
  background: var(--bg);
  border: 1px solid var(--border);
}

.progress {
  height: 100%;
  background: var(--accent);
  transition: width 0.3s;
}

/* ── graph view layout ─────────────────────────────────────────────── */
.graph-view {
  display: flex;
  flex-direction: column;
  height: 100%;
  min-height: 0;
}

.graph-toolbar {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 7px 14px;
  background: var(--bg-soft);
  border-bottom: 1px solid var(--border-strong);
  flex-shrink: 0;
  flex-wrap: wrap;
}

.graph-title {
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 40%;
  font-size: 12px;
}

.stat-chip {
  font-size: 10px;
  color: var(--text-dim);
  background: var(--bg);
  border: 1px solid var(--border);
  padding: 3px 10px;
  white-space: nowrap;
  letter-spacing: 0.1em;
}

.stat-chip .stage-times {
  opacity: 0.72;
}

.export-bar {
  display: flex;
  gap: 6px;
}

.graph-body {
  display: flex;
  flex: 1;
  min-height: 0;
}

.graph-side {
  width: 292px;
  flex-shrink: 0;
  overflow-y: auto;
  background: var(--bg-soft);
  border-right: 1px solid var(--border-strong);
  padding: 10px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.graph-canvas {
  flex: 1;
  min-width: 0;
  position: relative;
  background: var(--bg);
}

.graph-empty {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 100%;
  color: var(--text-dim);
  letter-spacing: 0.15em;
  text-transform: uppercase;
  font-size: 11px;
}

/* ── instrument panel sections ─────────────────────────────────────── */
.panel-section {
  background: var(--bg-card);
  border: 1px solid var(--border);
  padding: 12px;
}

.panel-section h4 {
  margin: 0 0 10px;
  font-size: 10px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--text);
  font-weight: 700;
  padding-bottom: 6px;
  border-bottom: 1px solid var(--border);
}

.panel-section h4::before {
  content: '// ';
  color: var(--accent);
}

/* search console */
.search {
  display: flex;
  align-items: center;
  gap: 8px;
  background: var(--bg-card);
  border: 1px solid var(--border-strong);
  padding: 5px 8px;
}

.search:focus-within {
  border-color: var(--accent);
}

.search input {
  flex: 1;
  background: transparent;
  border: none;
  outline: none;
  color: var(--text);
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: 0.06em;
  padding: 4px 0;
  min-width: 0;
}

.search-count {
  font-size: 10px;
  color: var(--text-dim);
  white-space: nowrap;
  letter-spacing: 0.08em;
}

/* path trace console */
.path-controls {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.path-controls select {
  background: var(--bg);
  color: var(--text);
  border: 1px solid var(--border-strong);
  padding: 6px 8px;
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: 0.04em;
}

.path-controls select:focus {
  border-color: var(--accent);
  outline: none;
}

.path-buttons {
  display: flex;
  gap: 6px;
}

.path-buttons button {
  flex: 1;
  font-size: 10px;
  padding: 7px;
}

.path-result {
  margin: 8px 0 0;
  font-size: 10px;
  color: var(--accent-hi);
  letter-spacing: 0.05em;
}

/* edge filter bank */
.filters {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.filter-group {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.filter-label {
  font-size: 10px;
  color: var(--text-dim);
  display: flex;
  justify-content: space-between;
  align-items: center;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.checkbox-row {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 10px;
  letter-spacing: 0.05em;
  cursor: pointer;
}

.checkbox-row input {
  accent-color: var(--accent);
  width: 13px;
  height: 13px;
}

.rel-name {
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  text-transform: uppercase;
}

.rel-count {
  color: var(--text-dim);
  font-size: 10px;
}

.relation-list {
  max-height: 140px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.filter-group input[type='range'] {
  width: 100%;
  accent-color: var(--accent);
  height: 14px;
}

/* legend */
.swatch-list {
  display: flex;
  flex-direction: column;
  gap: 5px;
  margin-bottom: 6px;
}

.swatch-row {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 10px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.swatch {
  width: 12px;
  height: 12px;
  border: 1px solid rgba(255, 255, 255, 0.25);
  flex-shrink: 0;
}

/* ── node record panel ─────────────────────────────────────────────── */
.node-panel {
  width: 304px;
  flex-shrink: 0;
  background: var(--bg-soft);
  border-left: 2px solid var(--accent);
  padding: 14px;
  overflow-y: auto;
}

.panel-kicker {
  font-size: 9px;
  letter-spacing: 0.2em;
  color: var(--accent-hi);
  text-transform: uppercase;
}

.node-panel-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--border);
}

.node-panel-header h3 {
  margin: 3px 0 0;
  font-family: var(--macro);
  font-size: 17px;
  letter-spacing: 0.01em;
  word-break: break-word;
}

.node-facts {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 5px 14px;
  margin: 12px 0;
}

.node-facts dt {
  color: var(--text-dim);
  font-size: 10px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.node-facts dd {
  margin: 0;
  font-size: 11px;
  text-align: right;
  word-break: break-word;
  letter-spacing: 0.04em;
}

.node-snippet {
  font-size: 11px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-left: 3px solid var(--accent);
  padding: 10px;
  margin-bottom: 12px;
  letter-spacing: 0.02em;
}

.node-snippet p {
  margin: 6px 0 0;
  color: var(--text-dim);
  line-height: 1.5;
}

.node-neighbors ul {
  list-style: none;
  margin: 8px 0 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.node-neighbors li {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 11px;
}

.node-neighbors li.neighbor-row {
  display: block;
  padding: 4px 0 6px;
  border-bottom: 1px solid var(--border);
}

.neighbor-line {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.neighbor-meta,
.neighbor-original,
.neighbor-evidence {
  margin: 3px 0 0 20px;
  color: var(--text-dim);
  font-size: 9px;
  letter-spacing: 0.03em;
  line-height: 1.45;
}

.neighbor-original {
  color: var(--warn);
}

.neighbor-evidence summary {
  cursor: pointer;
  color: var(--accent-hi);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.neighbor-evidence p {
  margin: 4px 0 0;
  color: var(--text-dim);
}

.neighbor-evidence small {
  color: var(--accent-hi);
}

.dir {
  color: var(--text-dim);
  font-weight: 700;
}

.dir.out {
  color: var(--accent-hi);
}

.dir.in {
  color: var(--warn);
}

.dir.both {
  color: var(--accent-hi);
}

.rel {
  color: var(--text-dim);
  font-style: normal;
  text-transform: uppercase;
  font-size: 9px;
  letter-spacing: 0.05em;
  max-width: 40%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.nb-name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* force-graph tooltip */
.fg-tip {
  background: var(--bg-card);
  border: 1px solid var(--border-strong);
  border-left: 3px solid var(--accent);
  padding: 6px 9px;
  font-size: 11px;
  line-height: 1.6;
  letter-spacing: 0.03em;
}

.fg-tip i {
  color: var(--accent-hi);
  font-style: normal;
  text-transform: uppercase;
  font-size: 10px;
}

.fg-tip b {
  color: var(--text);
  font-family: var(--mono);
}

